"""Frozen Sobol input design; targets are generated by the native PETSc solver."""
import numpy as np
import torch
import sampling_base as base
LOW=np.array([0.,0.,.2]);HIGH=np.array([1.,np.log1p(base.BETA_MAX),2.])

def transform(raw):
 z=raw[:,[0,1,3]].copy();z[:,1]=np.log1p(z[:,1]);return 2*(z-LOW)/(HIGH-LOW)-1

def sample(power,seed,kind):
 raw,mask=base.sample(power,seed,kind)
 u=torch.quasirandom.SobolEngine(9,scramble=True,seed=seed).draw_base2(power,dtype=torch.float64).numpy()
 raw[:,2]=2;raw[:,3]=.2+1.8*u[:,3];raw[:,4]=.4
 # Explicit law slices plus a continuous exponent distribution.
 mix=u[:,6]
 raw[mix<.15,3]=.2;raw[(mix>=.15)&(mix<.30),3]=2.
 return raw,mask

def audit():
    raw,_=sample(8,181001,"mixed")
    x=transform(raw)
    assert raw.shape==(256,5) and np.isfinite(x).all() and abs(x).max()<=1
    return dict(sampler="fixed Sobol design",label_solver="PETSc Newton/backtracking with continuation")
